`timescale 1ns/1ps
module sram_model #(
  parameter int  DW   = 16,
  parameter int  AW   = 10,
  parameter real T_CQ = 0.6               // clock-to-output
) (
  input  logic          clk,
  input  logic          cen,              // chip enable, active low
  input  logic          wen,              // write enable, active low
  input  logic [AW-1:0] a,
  input  logic [DW-1:0] d,
  output logic [DW-1:0] q
);
  logic [DW-1:0] mem [2**AW];
  reg notifier;                           // toggled on a timing violation

  always @(posedge clk)
    if (!cen) begin
      if (!wen) mem[a] <= d;              // write
      else      q <= #(T_CQ) mem[a];      // read, valid after tCQ
    end

  specify
    $setup(a,   posedge clk, 0.12, notifier);
    $hold (posedge clk, a,   0.05, notifier);
    $setup(d,   posedge clk, 0.10, notifier);
    $hold (posedge clk, d,   0.05, notifier);
    $setup(wen, posedge clk, 0.12, notifier);
    $setup(cen, posedge clk, 0.12, notifier);
  endspecify

  always @(notifier)                      // violation: output unknown
    if ($realtime > 0) begin              // ignore initialisation at time 0
      q <= 'x;
      $display("%t: timing violation in %m", $realtime);
    end

  // assertion: one clock after a read, q holds the word that was addressed
  a_read: assert property (
    @(posedge clk) (!cen && wen) |=> (q === mem[$past(a)])
  ) else $error("read data mismatch");
endmodule

`timescale 1ns/1ps
module tb;
  logic        clk = 0, cen = 1, wen = 1;
  logic [9:0]  a;
  logic [15:0] d, q;
  logic [15:0] ref_mem [int];             // reference model
  int          errors = 0;

  always #5 clk = ~clk;                   // 100 MHz
  sram_model #(.DW(16), .AW(10)) dut (.*);

  task automatic write(input logic [9:0] addr, input logic [15:0] data);
    @(negedge clk); cen = 0; wen = 0; a = addr; d = data;
    ref_mem[addr] = data;
  endtask

  task automatic read_check(input logic [9:0] addr);
    @(negedge clk); cen = 0; wen = 1; a = addr;
    @(negedge clk); cen = 1;              // q is valid now
    if (ref_mem.exists(addr) && q !== ref_mem[addr]) begin
      errors++;
      $error("addr %0h: read %h, expected %h", addr, q, ref_mem[addr]);
    end
  endtask

  initial begin
    repeat (500) write($urandom_range(0, 1023), $urandom);
    repeat (500) read_check($urandom_range(0, 1023));
    $display("test finished with %0d errors", errors);
    $finish;
  end
endmodule
